import{_ as e,c as l,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"泽水困","description":"周易折中 - 泽水困","frontmatter":{"title":"泽水困","description":"周易折中 - 泽水困"},"headers":[],"relativePath":"zh/classics/zhezhong/053.md","filePath":"zh/classics/zhezhong/053.md"}'),h={name:"zh/classics/zhezhong/053.md"};function n(d,a,p,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="泽水困" tabindex="-1">泽水困 <a class="header-anchor" href="#泽水困" aria-label="Permalink to “泽水困”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈困序〉：“卦升而不已必困，故受之以困。升者，自下而上，自下升上，以力进也。不已必困矣，故升之后受之以困也。困者，惫乏之义。为卦兑上而坎下，水居泽上，则泽中有水也；乃在泽下，枯涸无水之象，为困乏之义。又兑以阴在上，坎以阳居下，与上六在二阳之上，而九二陷于二阴之中，皆阴柔揜于阳刚，所以为困也。君子为小人所揜蔽，穷困之时也。”</p><p>困：亨，贞大人吉，无咎，有言不信</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>困者，穷而不能自振之义。坎刚为兑柔所揜，九二为二阴所揜，四五为上六所揜，所以为困。坎险兑说，处险而说，是身虽困而道则亨也。二五刚中，又有大人之象。占者处困能亨，则得其正矣。非大人其孰能之，故曰贞大人。曰大人者，明不正之小人不能当也。有言不信，又戒以当务晦黙，不可尚口益取穷困。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>如卦之才，则困而能亨，且得贞正，乃大人处困之道也，故能吉而无咎。大人处困，不唯其道自吉，乐天安命，乃不失其吉也。况随时善处，愎有裕乎？有言不信，当困而言，人谁信之？</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖达曰 ：困者，穷厄委顿之名。道穷力竭，不能自济，故名为困。小人遭困则穷斯滥矣，君子遇之则不改其操，处困而不失其自通之道，故曰困亨。处困而能自通，必是履正体大之人能济于困，然后得吉而无咎，故曰贞大人吉无咎。处困求济，在于正身脩徳，若巧言饰辞，人所不信，则其道弥穷，故诚之以有言不信也。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>困亨者，非谓处困而能亨也，盖困穷者所以动人之心，忍人之性，因屈以致伸，有必通之理也。然惟守正之夫人则能进徳于困而得其所以可通者尔，岂小人之所能乎？困者，君子道屈之时也，屈则不伸矣。有言不信，“信”字疑当作“伸”字解，盖有言而动见沮抑，乃是困厄之极，不特人疑之而不信也。夬卦“闻言不信”已不信人之言也，而夫子以“聪不明”解之，以“信”字对“聪”字，则“信”字当为疑信之信。此卦“有言不信”，人不行己之言也，而夫子以“尚口乃穷”解之，以“信”字对“穷”字，则“信”字当为屈伸之伸。</p><p>象曰：泽无水困，君子以致命遂志</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>水下漏则泽上枯，故曰泽无水。致命犹言授命，言持以与人而不之有也。能如是，则虽困而亨矣。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>泽无水，困乏之象也。君子当困穷之时，既尽其防虑之道而不得免，则命也。当推致其命以遂其志，知命之当然也，则穷塞祸患不以动其心，行吾义而已。苟不知命，则恐惧于险难，陨获于穷厄，所守亡矣，安能遂其为善之志乎？</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：泽无水，则水在泽下。水在泽下，困之象也。处困而屈其志者，小人也。君子固穷，道可忘乎？</p></li><li><p>郑氏汝谐曰 ：知其不可求而听其自至焉，致命也。在命者不可求，在志者则可遂，所谓从吾所好也。</p></li><li><p>冯氏当可曰 ：君子之处困也，命在天而致之志在我，则遂之。困而安于困者，命之致也；困而有不困者，志之遂也。若小人处之，则凡可以求幸免者无不为也，而卒不得免焉，则亦徒丧其所守而已矣。体坎险以致命，体兑说而遂志。</p></li><li><p>何氏楷曰 ：致犹委也。人不信其命，则死生祸福营为百端，居贞之志何以自遂？今一委之命，则不以命贰志者，夫且能以志立命。</p></li></ul><p>彖曰：困，刚揜也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦名。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>卦所以为困，以刚为柔所揜蔽也。陷于下而揜于上，所以困也。陷亦揜也。刚阳君子而为阴柔小人所揜蔽，君子之道困窒之时也。</p><p>险以说，困而不失其所亨，其唯君子乎；贞，大人吉，以刚中也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦德、卦体释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>以卦才言处困之道也。下险而上说，为处险而能说。虽在困穷艰险之中，乐天安义，自得其说，乐也。时虽困也，处不失义，则其道自亨。困而不失其所亨也，能如是者，其唯君子乎？若时当困而反亨，身虽亨，乃其道之困也。君子、大人通称，困而能贞，大人所以吉也。盖其以刚中之道也，五与二是也。非刚中，则遇困而失其正矣。当困而言，人所不信，欲以口免困，乃所以致穷也。以说处困，故有尚口之戒。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>郑氏汝谐曰 ：九二陷于中，九四、九五为上六所揜，是以为困。以上下卦言之，则合坎兑而成也。坎难也，兑说也。困而安于难，则不失其所亨；困而取说于人，尚口乃穷也。案此卦所以为刚揜者，本义备矣。盖诸卦之二五刚中，皆为阴揜者，惟困与节。然以二体言之，则节坎阳居上，兑阴居下，此困所以独为刚揜也。此义与卦象亦相贯，水在泽上，非泽之所能揜也；水在泽中，则为所揜矣。险以说者，非处险而说也，险有致说之理。“以”字与“而”字义不同也。惟险有致说之理，故困有所为亨者。然以小人处之，则困而困耳，不知其所为亨，故不能因困而得亨。因困而得其所亨者，非君子其孰能之？下“刚中之大人”，即不失所亨之君子也。指二五言。“尚口乃穷者”，处困之极务说于人，指上六言。</li></ul><p>初六：臀困于株木，入于幽谷，三岁不觌</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>臀，物之底也。困于株木，伤而不能安也。初六以阴柔处困之底，居暗之甚，故其象占如此。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>六以阴柔处于至卑，又居坎险之下，在困不能自济者也。必得在上刚明之人为援助，则可以济其困矣。初与四为正应，九四以阳而居阴，为不正，失刚而不中，又方困于阴揜，是恶能济人之困？犹株木之下，不能䕃覆于物。株木，无枝叶之木也。四近君之位，在他卦不为无助，以居困而不能庇物，故为株木。臀所以居也，臀困于株木，谓无所庇而不得安其居。居安则非困也。入于幽谷，阴柔之人非能安其所遇，既不能免于困，则益迷暗，妄动入于深困。幽谷，深暗之所也。方益入于困，无自出之势，故至于三岁不觌，终困者也。不觌，不遇其所亨也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰 ：初六在坎下，故为入于幽谷，即坎初爻“入于坎窞”也。</p></li><li><p>张氏清子曰 ：人之体行则趾为下，坐则臀为下。初六困而不行，此坐困之象也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>诗云：“出于幽谷，迁于乔木。”初六不能自迁于乔木，而惟坐困株木之下，则有愈入于幽谷而已。阴柔处困之最下，故其象如此。在人则卑暗穷陋而不能自拔者，言臀者，况其坐而不迁也。</p><p>象曰：入于幽谷，幽不明也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>幽不明也，谓益入昏暗，自陷于深困也。明则不至于陷矣。</p><p>九二：困于酒食，朱绂方来，利用亨祀，征凶无咎</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>困于酒食，厌饫苦恼之意。酒食，人之所欲，然醉饱过宜，则是反为所困矣。朱绂方来，上应之也。九二有刚中之徳，以处困时，虽无凶害，而反困于得其所欲之多，故其象如此。而其占，利以享祀，若征行则非其时，故凶而于义为无咎也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>酒食，人所欲而所以施惠也。二以刚中之才而处困之时，君子安其所遇，虽穷厄险难，无所动其心，不恤其为困也。所困者，唯困于所欲耳。君子之所欲者，泽天下之民，济天下之困也。二未得遂其欲施其惠，故为困于酒食也。大人君子怀其道而困于下，必得有道之君求而用之，然后能施其所蕴。二以刚中之徳困于下，上有九五刚中之君，道同徳合，必来相求，故云朱绂方来。方来，方且来也。朱绂，王者之服蔽膝也，以行来为义，故以蔽膝言之。利用享祀，享祀以至诚通神明也。在困之时，利用至诚如享祀然，其徳至诚自能感通于上。自昔贤哲困于幽远而徳卒升闻，道卒为用者，唯自守至诚而已。征凶无咎，方困之时，若不至诚安处以俟命，往而求之，则犯难得凶，乃自取也。将谁咎乎？不度时而征，乃不安其所为，困所动也，失刚中之徳，自取凶悔，何所怨咎？诸卦二五以阴阳相应而吉，唯小畜与困乃厄于阴，故同道相求。小畜阳为阴所畜，困阳为阴所揜也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>石氏介曰 ：朱绂，祭服，谓可衣朱绂而享宗庙也。征凶，既在险中，何可以行？无咎，以其居阳明之徳可以无咎。案：小人以身穷为困，君子以道穷为困。卦之三阳，所谓君子也。所困者非身之穷，乃道之穷也。故二五则绂服荣于躬，四则金车宠于行。然而道之不通，则其荣宠也适以为困而已矣。然荣宠亦非无故而来，神明之意必有在焉。惟竭诚以求，当神明之意，则终有通时矣。故虽当困之时，征行必凶，而其要无咎也。用享祀者，谓服此朱绂，用此酒食以享之，喻所得之爵禄不敢以之自奉，而以为竭诚尽职之其也。《书》曰：“予不敢宿，则禋于文王武王。”意义相近。</li></ul><p>象曰：困于酒食，中有庆也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>虽困于所欲，未能施惠于人，然守其刚中之德，必能致亨而有福庆也。虽使时未亨通，守其中德亦君子之道，亨乃有庆也。</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>二有中德，故能以酒食亨祀而有福庆。</p><p>六三：困于石，据于蒺藜，入于其宫，不见其妻，凶</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>阴柔而不中正，故有此象。而其占则凶。石指四，蒺藜指二，宫谓三而妻则六也。其义则系辞备矣。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>六三以阴柔不中正之质，处险极而用刚，居阳用刚也，不善处困之甚者也。石，坚重难胜之物；蒺藜，刺不可据之物。三以刚险而上进，则二阳在上，力不能胜，坚不可犯，益自困耳，困于石也。以不善之徳居九二刚中之上，其不安犹藉刺，据于蒺藜也。进退既皆益困，欲安其所益不能矣。宫，其居所安也；妻，所安之主也。知进退之不可而欲安其居，则失其所安矣。进退与处皆不可，唯死而已，其凶可知。系辞曰：“非所困而困焉，名必辱；非所据而据焉，身必危。”既辱且危，死期将至，妻其可得见邪？二阳不可犯也，而犯之以取困，是非所困而困也，名辱其事恶也。三在二上固为据之，然苟能谦柔以下之，则无害矣。乃用刚险以乘之，则不安而取困，如据蒺藜也。如是，死期将至，所安之主可得而见乎？</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>三阴皆非能处困者。初在下，坐而困者也；三居进退之际，行而困者也。伤于外者必反其家，而又无所归，甚言妄行取困其极如此。</p><p>象曰：据于蒺藜，乘刚也；入于其宫，不见其妻，不祥也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>据于蒺藜，谓乘九二之刚不安，犹藉刺也。不祥者，不善之徴，失其所安者不善之效，故云不见其妻不祥也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>郑氏汝谐曰 ：进厄于四，故困于石；退乘二之刚，故据于蒺藜。上其宫也，其宫可入，而以柔遇柔，非其配也。以此处困，不祥莫甚焉。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>爻有众喻，而传偏举一者，举其重者也。易乘刚之义最重，故睽三见舆曵，此爻据于蒺藜，皆以其乘刚言之。</p><p>九四：来徐徐，困于金车，吝有终</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>初六、九四之正应，九四处位不当，不能济物，而初六方困于下，又为九二所隔，故其象如此。然邪不胜正，故其占虽为可吝而必有终也。金车为九二象，未详，疑坎有轮象也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>唯力不足，故困亨。困之道，必由援助。当困之时，上下相求，理当然也。四与初为正应，然四以不中正处困，其才不足以济人之困。初比二，二有刚中之才，足以拯困，则宜为初所从矣。金刚也，车载物者也，二以刚在下，载故谓之金车。四欲从初而阻于二，故其来迟疑而徐徐，是困于金车也。已之所应，疑其少，已而之他，将从之，则犹豫不敢遽前，岂不可羞吝乎？有终者，事之所归者正也。初四正应，终必相从也。寒士之妻，弱国之臣，各安其正而已。苟择势而从，则恶之大者，不容于世矣。二与四皆以阳居阴，而二以刚中之才，所以能济困也。居阴者尚柔，得中者不失刚柔之宜也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏瑗曰 ：徐徐者，舒缓不敢决进也。案：来徐徐者，喻君子当困时不欲上进也。困于金车者，招我以车，不容不来也。如是，则可羞吝矣。然上近九五之刚中正，乃卦所谓大人者，与之同徳，终有亨道。</li></ul><p>象曰：来徐徐，志在下也；虽不当位，有与也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四应于初而隔于二，志在下求，故徐徐而来。虽居不当位为未善，然其正应相与，故有终也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏浚曰 ：四与五同为上六所掩，进而见掩，岂君子直遂之时耶？惟沈濳以养其晦，从容以俟其几。故五曰“乃徐”，四曰“徐徐”，志在下者，四位虽上而心则下也。然四五合德，天下之事终以舒徐济之，故曰“有与”又曰“有终”。</p></li><li><p>何氏楷曰 ：五为近比，则四之所与者。</p></li></ul><p>九五：劓刖，困于赤绂，乃徐有说，利用祭祀</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>劓刖者，伤于上下。上下既伤，则赤绂无所用而反为困矣。九五当困之时，上为阴揜，下则乘刚，故有此象。然刚中而说体，故能迟久而有说也。占具象中，又利用祭祀，久当获福。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>截鼻曰劓，伤于上也；去足为刖，伤于下也。上下皆揜于阴，为其伤害，劓刖之象也。五君位也，人君之困由上下无与也。赤绂，臣下之服，取行来之义，故以绂言。人君之困，以天下不来也。天下皆来，则非困也。五虽在困，而有刚中之徳，下有九二刚中之贤，道同徳合，徐必相应而来，共济天下之困，是始困而徐有喜说也。利用祭祀，祭祀之事必致其诚敬而后受福。人君在困时，宜念天下之困，求天下之贤，若祭祀然，致其诚敬，则能致天下之贤，济天下之困矣。五与二同徳而云上下无与，何也？曰：阴阳相应者，自然相应也，如夫妇骨肉分定也。五与二皆阳爻，以刚中之徳同而相应相求，而后合者也，如君臣朋友义合也。方其始困，安有上下之与？有与则非困，故徐合而后有说也。二云“享祀”，五云“祭祀”，大意则宜用至诚乃受福也。祭与祀、享，泛言之则可通，分而言之，祭天神，祀地示，享人鬼。五君位言祭，二在下言享，各以其所当用也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏应麟曰 ：困九五曰“利用祭祀”，李公晦谓“明虽困于人而幽可感于神”，岂不以人不能知而鬼神独知之乎？愚谓孔子云“知我者其天乎”，韩子云“惟乖于时乃与天通”，不求人知而求天知，处困之道也。案：九五不取君象，但取位高而益困者耳。其象与九二同，但二则朱绂方将来，五则高位而已，困于赤绂矣。乃徐有说者，五兑体，故能从容以处之而有馀裕也。利用祭祀之义，亦与二同。</li></ul><p>象曰：劓刖，志未得也；乃徐有说，以中直也；利用祭祀，受福也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>始为阴揜，无上下之与，方困未得志之时也。徐而有说，以中直之道得在下之贤共济于困也。不曰中正与二合者，云直乃宜也。直比正意差缓，尽其诚意如祭祀然，以求天下之贤，则能亨天下之困而享受其福庆也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>陆氏希声曰 ：困穷而通，德辨而明，中正道行，志则大遂，故乃徐有说也。</li></ul><p>上六：困于葛藟，于臲卼，曰动悔有悔，征吉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以阴柔处困极，故有“困于葛藟，于臲卼，曰动悔”之象。然物穷则变，故其占曰：“若能有悔，则可以征而吉矣。”</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>物极则反，事极则变。困既极矣，理当变矣。葛藟，纒束之物；臲卼，危动之状。六处困之极，为困所纒束，而居最高危之地，困于葛藟与臲卼也。动悔，动辄有悔，无所不困也。有悔，咎前之失也，曰自谓也。若能曰：“如是动皆得悔”，当变前之所为，有悔也。能悔则往而得吉也，困极而征，则出于困矣，故吉。三以阴在下卦之上而凶，上居一卦之上而无凶，何也？曰：三居刚而处险，困而用刚险，故凶；上以柔居说，唯为困极耳，困极则有变，困之道也。困与屯之上，皆以无应居卦终。屯则泣血涟如，困则有悔征吉。屯险极而困说体，故也以说顺进，可以离乎困也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰 ：此彖所谓“尚口乃穷”也。若能断葛藟而不牵辞，臲卼而不居，行而去之，吉孰加焉？</p></li><li><p>易氏祓曰 ：阳刚不可终困，而二四五皆不言吉。阴柔未免乎困，而上独言吉者，困极则变，如否之有泰，虽险而终济也。</p></li><li><p>徐氏几曰 ：震无咎者存乎悔。困已极矣，有悔则可出困而征吉，困穷而通，其谓是夫。</p></li><li><p>吴氏曰愼曰 ：困非自己致而时势适逄者，则当守其刚中之徳，是谓困而不失其所亨也。其道主于贞。若困由已之柔暗而致者，则当变其所为，以免于困也。其道主于悔。学者深察乎此，则处困之道异宜而各得矣。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>处困贵于说，而上为说之主也。故虽当困极，而尚有征吉之占，异乎初与三之坐困行塞者也。然为兑主，则又有尚口之象。尚口则支离缴绕，如困于葛藟然，将且臲卼不安，而失其所为说矣。故必悔悟而离去之，则吉。</p><p>象曰：困于葛藟，未当也；动悔有悔，吉行也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>为困所缠而不能变，未得其道也，是处之未当也。知动则得悔，遂有悔而去之，可出于困，是其行而吉也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>陆氏希声曰 ：行而获吉，故曰“变乃通也”。</p></li><li><p>田氏畴曰 ：诸家皆以“吉行也”三字为一句，非也。盖“动悔有悔吉”是句，“行也”是句。“动悔有悔”之所以吉者，以能行而得之也。“行也”二字，乃是解“征吉”之义。</p></li></ul><p>总论</p><ul><li>龚氏焕曰：卦以柔揜刚而为困，主乎阳而言也。而阴之困为尤甚。《彖传》曰：“困而不失其所亨，其惟君子乎？”三刚爻之谓矣。</li></ul>',109)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
